import pulp

# -----------------------------
# Data
# -----------------------------
plants = ["Alpha", "Beta", "Gamma", "Delta", "Epsilon", "Zeta", "Eta", "Theta"]
cities = ["Delta", "Epsilon", "Zeta", "Eta", "Theta", "Iota", "Kappa", "Lambda"]

# Generation capacities (MW) of each plant
supply = {
    "Alpha": 75,
    "Beta": 64,
    "Gamma": 60,
    "Delta": 40,
    "Epsilon": 57,
    "Zeta": 58,
    "Eta": 47,
    "Theta": 40,
}

# Demand (MW) of each city
demand = {
    "Delta": 31,
    "Epsilon": 42,
    "Zeta": 40,
    "Eta": 78,
    "Theta": 85,
    "Iota": 57,
    "Kappa": 68,
    "Lambda": 40,
}

# Transmission line capacities (MW) and unit costs ($/MW)
# Structure: caps[plant][city] = capacity, costs[plant][city] = cost
caps = {
    "Alpha": {
        "Delta": 91, "Epsilon": 16, "Zeta": 97, "Eta": 15,
        "Theta": 85, "Iota": 16, "Kappa": 69, "Lambda": 7,
    },
    "Beta": {
        "Delta": 89, "Epsilon": 79, "Zeta": 70, "Eta": 47,
        "Theta": 98, "Iota": 81, "Kappa": 17, "Lambda": 77,
    },
    "Gamma": {
        "Delta": 35, "Epsilon": 7, "Zeta": 10, "Eta": 17,
        "Theta": 98, "Iota": 44, "Kappa": 16, "Lambda": 80,
    },
    "Delta": {
        "Delta": 55, "Epsilon": 95, "Zeta": 21, "Eta": 78,
        "Theta": 83, "Iota": 72, "Kappa": 30, "Lambda": 40,
    },
    "Epsilon": {
        "Delta": 42, "Epsilon": 25, "Zeta": 28, "Eta": 80,
        "Theta": 33, "Iota": 22, "Kappa": 21, "Lambda": 34,
    },
    "Zeta": {
        "Delta": 38, "Epsilon": 68, "Zeta": 43, "Eta": 23,
        "Theta": 99, "Iota": 83, "Kappa": 39, "Lambda": 31,
    },
    "Eta": {
        "Delta": 15, "Epsilon": 22, "Zeta": 89, "Eta": 57,
        "Theta": 28, "Iota": 30, "Kappa": 80, "Lambda": 7,
    },
    "Theta": {
        "Delta": 49, "Epsilon": 73, "Zeta": 89, "Eta": 66,
        "Theta": 91, "Iota": 21, "Kappa": 99, "Lambda": 39,
    },
}

costs = {
    "Alpha": {
        "Delta": 10, "Epsilon": 6, "Zeta": 10, "Eta": 3,
        "Theta": 6, "Iota": 4, "Kappa": 3, "Lambda": 5,
    },
    "Beta": {
        "Delta": 9, "Epsilon": 3, "Zeta": 9, "Eta": 10,
        "Theta": 2, "Iota": 8, "Kappa": 8, "Lambda": 4,
    },
    "Gamma": {
        "Delta": 3, "Epsilon": 10, "Zeta": 6, "Eta": 10,
        "Theta": 4, "Iota": 2, "Kappa": 9, "Lambda": 8,
    },
    "Delta": {
        "Delta": 4, "Epsilon": 5, "Zeta": 7, "Eta": 5,
        "Theta": 9, "Iota": 4, "Kappa": 6, "Lambda": 7,
    },
    "Epsilon": {
        "Delta": 6, "Epsilon": 1, "Zeta": 1, "Eta": 4,
        "Theta": 4, "Iota": 10, "Kappa": 3, "Lambda": 9,
    },
    "Zeta": {
        "Delta": 8, "Epsilon": 2, "Zeta": 5, "Eta": 9,
        "Theta": 5, "Iota": 8, "Kappa": 7, "Lambda": 6,
    },
    "Eta": {
        "Delta": 7, "Epsilon": 1, "Zeta": 2, "Eta": 1,
        "Theta": 6, "Iota": 3, "Kappa": 5, "Lambda": 10,
    },
    "Theta": {
        "Delta": 9, "Epsilon": 8, "Zeta": 5, "Eta": 9,
        "Theta": 7, "Iota": 8, "Kappa": 6, "Lambda": 4,
    },
}

# -----------------------------
# Model
# -----------------------------
model = pulp.LpProblem("Power_Grid_Transmission_MinCost", pulp.LpMinimize)

# Decision variables: flow from plant i to city j (continuous, >=0)
flow = pulp.LpVariable.dicts(
    "flow",
    ((i, j) for i in plants for j in cities),
    lowBound=0,
    cat="Continuous",
)

# Objective: minimize total transmission cost
model += pulp.lpSum(costs[i][j] * flow[(i, j)] for i in plants for j in cities)

# Supply constraints: each plant cannot exceed its generation capacity
for i in plants:
    model += (
        pulp.lpSum(flow[(i, j)] for j in cities) <= supply[i],
        f"Supply_{i}",
    )

# Demand constraints: each city must receive exactly its demand
for j in cities:
    model += (
        pulp.lpSum(flow[(i, j)] for i in plants) == demand[j],
        f"Demand_{j}",
    )

# Transmission line capacity constraints
for i in plants:
    for j in cities:
        model += (
            flow[(i, j)] <= caps[i][j],
            f"Cap_{i}_{j}",
        )

# -----------------------------
# Solve
# -----------------------------
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# -----------------------------
# Output
# -----------------------------
print("Status:", pulp.LpStatus[model.status])
print(f"Total transmission cost = ${pulp.value(model.objective):.2f}\n")

print("Optimal flows (MW):")
for i in plants:
    for j in cities:
        qty = flow[(i, j)].varValue
        if qty is not None and qty > 1e-5:  # display only positive flows
            print(f"  {i} -> {j}: {qty:.2f} MW")
